mapper.select:
SELECT t2.`id`, t2.`camera_patrol_line_id`, t2.`auth_type`, t2.`auth_ids`, t2.`auth_config`, t2.`tenant`, t2.`deleted`, t2.`create_by`, t2.`creator_id`, t2.`creator_type`, t2.`create_time`, t2.`update_by`, t2.`updater_id`, t2.`updater_type`, t2.`update_time` FROM `camera_patrol_line` t1 INNER JOIN `camera_patrol_person` t2 ON t1.`id` = t2.`camera_patrol_line_id`
and t1.`enabled` = #{enabled}
and t1.`create_time` >= #{period.begin}
and t1.`create_time` <= #{period.end}
